import {createApp,ref} from 'vue/dist/vue.esm-bundler.js';
createApp({setup(){return {message:ref(''),query:ref(''),items:['Apple','Orange']};},template:`<main><h1>Framework fixture</h1><form @submit.prevent="message='Invalid password'"><label>Email<input name="email" type="email"></label><label>Password<input name="password" type="password"></label><button>Log in</button><p role="alert">{{message}}</p></form><label>Search<input v-model="query"></label><ul><li v-for="item in items.filter(x=>x.toLowerCase().includes(query.toLowerCase()))" :key="item">{{item}}</li></ul></main>`}).mount('#app');
